// Private Root-authorized controlled Original declaration capture + saved-scene composition.
use raptor_replica::{assets::{Catalog,Sprite},content::{ContentId,Registry},modding::ScriptRuntime,persistence::Pilot,simulation::{Input,Outcome,World},hd::HdAssets,render::{Canvas,upscale,nearest,prefers_nearest,legacy_light_table,shade_air_shadow,shade_ground_shadow},terrain_hd::{selected_art,TerrainHd,Replacement,RetainedOriginalPlacement,PaletteConstraintPlacement,OverlayResult}};
use serde_json::{json,Value};
use std::{path::Path,io::Write,collections::BTreeSet};
fn read(p:&Path)->Value{serde_json::from_slice(&std::fs::read(p).unwrap()).unwrap()}
fn id(v:&Value)->u32{u32::from_str_radix(v.as_str().unwrap(),16).unwrap()}
fn ints(v:&Value)->Vec<u16>{v.as_array().unwrap().iter().map(|v|u16::try_from(v.as_u64().unwrap()).unwrap()).collect()}
fn at(v:&Value,scale:usize)->[i32;2]{let mut p=[0;2];for k in 0..2{let x=v["previous_position"][k].as_f64().unwrap()as f32;let y=v["current_position"][k].as_f64().unwrap()as f32;p[k]=((x+(y-x)*0.5)*scale as f32).round()as i32;}p}
fn snapshot(w:&World,r:&Registry,entity:u64)->Value{
 let m=&r.missions[&w.mission];assert_eq!(m.columns,9);let offset=200-(m.layout.len()/9)as i32*32+w.scroll;let phase=offset.rem_euclid(32);let origin=offset-phase;
 let mut terrain=Vec::new();for(n,index)in m.layout.iter().enumerate(){let row=n/9;let col=n%9;let y=origin+row as i32*32;if !(-66..234).contains(&y){continue;}let art=selected_art(&m.tiles[*index],true,w.terrain_dead[n],w.terrain_settled[n]);terrain.push(json!({"asset":format!("{:05x}",art.asset.unwrap()),"full_art":art,"layout_index":n,"row":row,"column":col,"position_before_plus34":[16+col as i32*32,y],"terrain_dead":w.terrain_dead[n],"terrain_settled":w.terrain_settled[n]}));}
 let actors:Vec<_>=w.enemies.iter().map(|e|{let d=&r.enemies[&e.definition];let a=d.art.as_ref().unwrap();assert!(e.art_frame<a.frames);json!({"entity":e.entity,"definition":e.definition,"asset":format!("{:05x}",a.asset.unwrap()+e.art_frame),"full_art":a,"frame":e.art_frame,"health":e.health,"age":e.age,"ground":d.ground,"shadow_enabled":d.legacy.as_ref().unwrap().fields[11]!=0,"previous_position":[e.px,e.py],"current_position":[e.x,e.y],"logical_size":[e.width,e.height],"actual_definition":d,"actual_enemy":e})}).collect();
 let effects:Vec<_>=w.effects.iter().map(|e|{let(base,frames)=e.kind.artwork();let frame=e.age.saturating_sub(1).min(frames-1);json!({"asset":format!("{:05x}",base+frame),"frame":frame,"kind":format!("{:?}",e.kind),"ground":e.ground,"previous_position":[e.px,e.py],"current_position":[e.x,e.y],"actual":e})}).collect();
 json!({"capture_entity":entity,"mission":w.mission,"tick":w.tick,"scroll":w.scroll,"alpha":0.5,"scroll_phase":phase,"terrain":terrain,"enemies":actors,"main_effects":effects,"actual_World_snapshot":w,"controlled_mission_not_natural_mission_claim":true,"no_active_entity_position_health_frame_path_rng_override":true})
}
fn capture(a:&[String]){
 assert_eq!(a.len(),5,"capture DATA FRESH_CAPTURE_JSON FAMILY");let output=Path::new(&a[3]);assert!(!output.exists());
 let(target,def,mission_name,frame_count,width,height,health,original_name)=match a[4].as_str(){"ship09"=>(0x2009fu32,"base:enemy_1_12","base:sector_2_wave_9",2usize,72i32,40i32,30,"SHIP09G2_PIC"),_=>panic!("unknown family")};
 let cat=Catalog::open(&a[2]).unwrap();assert_eq!(cat.id(original_name).unwrap(),target);let mut registry=Registry::base(&cat).unwrap();let mission:ContentId=mission_name.into();let d=&registry.enemies[&ContentId::from(def)];let art=d.art.as_ref().unwrap();assert_eq!(art.asset,Some(target));assert_eq!(art.frames as usize,frame_count);assert_eq!((art.logical_width,art.logical_height),(width as u32,height as u32));assert!(d.ground);assert_eq!(d.health,health);assert_eq!(d.legacy.as_ref().unwrap().fields[11],0);let source_definition=serde_json::to_value(d).unwrap();let original=registry.missions[&mission].clone();let chosen=original.spawns.iter().find(|sp|sp.enemy.0==def && sp.difficulty==4).unwrap().clone();
 registry.missions.get_mut(&mission).unwrap().spawns=vec![chosen.clone()];let controlled=serde_json::to_value(&registry.missions[&mission]).unwrap();let mut pilot=Pilot::default();pilot.mission=mission.clone();pilot.difficulty=2;pilot.validate(&registry,&[]).unwrap();let mut w=World::new(&mission,&pilot,&registry).unwrap();let expected_seed=8192;assert_eq!((w.tick,w.scroll,w.rng.seed),(0,0,expected_seed));let initial=serde_json::to_value(&w).unwrap();let mut scripts=ScriptRuntime::new();let mut states=Vec::new();let mut logs=Vec::new();let mut birth=Value::Null;let mut entity=None;let mut seen=BTreeSet::new();let mut scenes=Vec::new();let mut order=Vec::new();let maximum_steps=chosen.tick+700;
 for _ in 0..maximum_steps{
  if w.outcome!=Outcome::Playing{break;}let input=Input::default();logs.push(json!({"before_tick":w.tick,"input":input}));w.step(input,&registry,&mut scripts).unwrap();assert_eq!(serde_json::to_value(&registry.missions[&mission]).unwrap(),controlled);assert_eq!(serde_json::to_value(&registry.enemies[&ContentId::from(def)]).unwrap(),source_definition);
  if entity.is_some()&&!w.enemies.iter().any(|e|Some(e.entity)==entity){break;}
  if let Some(e)=w.enemies.iter().find(|e|e.definition.0==def){assert_eq!(w.enemies.len(),1);if entity.is_none(){entity=Some(e.entity);birth=json!({"tick":w.tick,"enemy":e,"rng_seed":w.rng.seed});}assert_eq!(entity,Some(e.entity));assert_eq!(e.pinned_art_frame,None);assert!((e.art_frame as usize)<frame_count);states.push(json!({"tick":w.tick,"entity":e.entity,"age":e.age,"health":e.health,"frame":e.frame,"art_frame":e.art_frame,"frame_timer":e.frame_timer,"animation_on":e.animation_on,"previous":[e.px,e.py],"current":[e.x,e.y]}));
   let visible=e.health==health&&e.px>=0&&e.x>=0&&e.px+e.width<=320&&e.x+e.width<=320&&e.py>=0&&e.y>=0&&e.py+e.height<=200&&e.y+e.height<=200;
   if visible&&seen.insert(e.art_frame){order.push(json!({"tick":w.tick,"frame":e.art_frame}));scenes.push(snapshot(&w,&registry,e.entity));if seen.len()==frame_count{break;}}
  }
 }
 scenes.sort_by_key(|scene|scene["enemies"][0]["frame"].as_u64().unwrap());let complete=seen.len()==frame_count;
 let value=json!({"status":if complete{"ACTUAL_CONTROLLED_ORIGINAL_SHIP09G2_COMPLETE2_CAPTURED"}else{"INCOMPLETE_CONTROLLED_CAPTURE_STOP_NO_RETRY"},"family":a[4],"target_base":target,"frame_count":frame_count,"original_source_mission":original,"controlled_mission":controlled,"retained_exact_source_spawn":chosen,"suppressed_other_spawns":original.spawns.len()-1,"Source_definition_unchanged":source_definition,"starting_pilot":pilot,"starting_seed":expected_seed,"initial_World":initial,"actual_inputs":logs,"actual_birth":birth,"actual_state_progression":states,"chronological_capture_order":order,"scenes":scenes,"actual_final_tick":w.tick,"actual_outcome":format!("{:?}",w.outcome),"maximum_steps":maximum_steps,"testing_controls":"Original mission clone retains first exact declared family spawn, all other declarations suppressed before World. Default legal pilot2, no inputs; no healing/loadout/entity position/frame/health/RNG overrides.","not_natural_mission_or_survival_purchase_proof":true,"World_calls":1,"HD_render_QA_calls":0});
 let mut f=std::fs::OpenOptions::new().create_new(true).write(true).open(output).unwrap();serde_json::to_writer_pretty(&mut f,&value).unwrap();f.write_all(b"\n").unwrap();println!("capture complete={complete}; tick{}; phases{:?}",w.tick,seen);if !complete{std::process::exit(2);}
}
fn select(cat:&Catalog,hd:&mut HdAssets,id:u32,s:usize,pal:&[[u8;3];256])->Sprite{hd.sprite(id,s,pal).unwrap().unwrap_or_else(||{let a=cat.sprite(id).unwrap();if prefers_nearest(id){nearest(&a,s)}else{upscale(&a,s).unwrap()}})}
fn emit(out:&Path,name:&str,s:&Sprite)->Value{let mut bytes=Vec::new();let mut classes=Vec::new();for &v in &s.pixels{assert!(v<=256);bytes.extend_from_slice(&v.to_le_bytes());classes.push(if v>=240&&v<=255{v as u8}else{0});}let ni=format!("{name}.u16le.gz");let nc=format!("{name}.classes.gz");for(n,b)in[(&ni,bytes),(&nc,classes)]{let mut z=flate2::write::GzEncoder::new(std::fs::File::create(out.join(n)).unwrap(),flate2::Compression::default());z.write_all(&b).unwrap();z.finish().unwrap();}json!({"indices":ni,"classes":nc,"width":s.width,"height":s.height,"samples":s.pixels.len()})}
fn effects(c:&mut Canvas,cat:&Catalog,hd:&mut HdAssets,s:&Value,ground:bool,pal:&[[u8;3];256]){for fx in s["main_effects"].as_array().unwrap().iter().filter(|f|f["ground"].as_bool().unwrap()==ground){let asset=id(&fx["asset"]);let src=cat.sprite(asset).unwrap();let im=select(cat,hd,asset,c.scale,pal);let x=(fx["previous_position"][0].as_f64().unwrap()+(fx["current_position"][0].as_f64().unwrap()-fx["previous_position"][0].as_f64().unwrap())*0.5)as f32-src.width as f32/2.;let y=(fx["previous_position"][1].as_f64().unwrap()+(fx["current_position"][1].as_f64().unwrap()-fx["previous_position"][1].as_f64().unwrap())*0.5)as f32-src.height as f32/2.;c.blit(&im,(x*c.scale as f32).round()as i32,(y*c.scale as f32).round()as i32);}}
fn compose(a:&[String]){
 assert_eq!(a.len(),8,"compose DATA CAPTURE BASELINE_PACK TARGET_PACK BANK FRESH_OUTPUT");let out=Path::new(&a[7]);assert!(!out.exists());let cap=read(Path::new(&a[3]));assert_eq!(cap["status"],"ACTUAL_CONTROLLED_ORIGINAL_SHIP09G2_COMPLETE2_CAPTURED");assert_eq!(cap["scenes"].as_array().unwrap().len(),2);let cat=Catalog::open(&a[2]).unwrap();let pal=cat.palette().unwrap();let vga=pal.map(|v|v.map(|c|c>>2));let gt=legacy_light_table(&vga,-9);let air=legacy_light_table(&vga,-6);let mut foreign=HdAssets::load_lazy(Path::new(&a[4]),&cat,None);let mut target=HdAssets::load(Path::new(&a[5]),&cat);assert!(foreign.diagnostics.is_empty()&&target.diagnostics.is_empty(),"foreign {:?}; target {:?}",foreign.diagnostics,target.diagnostics);let bank=read(Path::new(&a[6]));assert_eq!(bank.as_array().unwrap().len(),2);let mut sprites=Vec::new();let mut components=Vec::new();
 for f in 0..2{let asset=id(&bank[f]["asset"]);assert_eq!(asset,0x2009f+f as u32);let src=cat.sprite(asset).unwrap();assert_eq!((src.width,src.height),(72,40));assert_eq!(src.pixels,ints(&bank[f]["source"]["indices"]));let mut scales=Vec::new();for scale in 1..=4{assert!(foreign.sprite(asset,scale,&pal).unwrap().is_none());let selected=target.sprite(asset,scale,&pal).unwrap().unwrap();assert_eq!(selected.pixels,ints(&bank[f]["scales"][scale-1]["indices"]));let original=upscale(&src,scale).unwrap();scales.push((original,selected));}sprites.push(scales);}
 std::fs::create_dir(out).unwrap();for f in 0..2{for scale in 1..=4{components.push(json!({"frame":f,"scale":scale,"actual_Original_ScaleNx":emit(out,&format!("component-f{f}-s{scale}-OriginalNx"),&sprites[f][scale-1].0),"measured_selected":emit(out,&format!("component-f{f}-s{scale}-selected"),&sprites[f][scale-1].1)}));}}
 let mut rows=Vec::new();for(si,s)in cap["scenes"].as_array().unwrap().iter().enumerate(){let actor=&s["enemies"][0];let frame=actor["frame"].as_u64().unwrap()as usize;let target_asset=id(&actor["asset"]);assert_eq!(target_asset,0x2009f+si as u32);assert_eq!(frame,si);assert_eq!(actor["ground"],true);assert_eq!(actor["shadow_enabled"],false);assert_eq!(actor["health"],30);let width=72;let height=40;
  for scale in 1..=4{let mut logical=Canvas{scale:1,image:Sprite{width:320,height:268,pixels:vec![0;320*268]}};for t in s["terrain"].as_array().unwrap(){logical.blit(&cat.sprite(id(&t["asset"])).unwrap(),t["position_before_plus34"][0].as_i64().unwrap()as i32,t["position_before_plus34"][1].as_i64().unwrap()as i32+34);}let orig=upscale(&logical.image,scale).unwrap();let mut replacements=Vec::new();let mut retained=Vec::new();let mut domains=Vec::new();for t in s["terrain"].as_array().unwrap(){if let Some((image,details,domain))=foreign.terrain_sprite_with_palette(id(&t["asset"]),scale,&pal).unwrap(){if let Some(details)=details{retained.push(RetainedOriginalPlacement{replacement_index:replacements.len(),details});}if let Some(palette)=domain{domains.push(PaletteConstraintPlacement{replacement_index:replacements.len(),palette});}replacements.push(Replacement{image,position:[t["position_before_plus34"][0].as_i64().unwrap()as i32,t["position_before_plus34"][1].as_i64().unwrap()as i32+34],logical_size:[32,32]});}}
   let mut th=TerrainHd::default();let bg=th.compose_with_palette_constraints(&orig,&replacements,&retained,&domains,scale,&pal);assert!(bg.results.iter().all(|v|*v==OverlayResult::Applied));let y=((-34.+s["scroll_phase"].as_i64().unwrap()as f32-0.5)*scale as f32).round()as i32;let mut terrain=Canvas::new(scale);terrain.clear(0);terrain.blit(&bg.image,0,y);let mut roles=Vec::new();let mut bodies=Vec::new();let p=at(actor,scale);assert!(p[0]>=0&&p[1]>=0&&p[0]+width*scale as i32<=320*scale as i32&&p[1]+height*scale as i32<=200*scale as i32);
   for role in 0..3{let mut c=Canvas{scale,image:terrain.image.clone()};let mut order=Vec::new();let mut shadows=Vec::new();for ground in[true,false]{let mut count=0;for e in s["enemies"].as_array().unwrap().iter().filter(|e|e["ground"].as_bool().unwrap()==ground&&e["shadow_enabled"].as_bool().unwrap()){if count>=if ground{25}else{50}{break;}let mask=cat.sprite(id(&e["asset"])).unwrap();let x=(e["previous_position"][0].as_f64().unwrap()+(e["current_position"][0].as_f64().unwrap()-e["previous_position"][0].as_f64().unwrap())*0.5)as f32;let yy=(e["previous_position"][1].as_f64().unwrap()+(e["current_position"][1].as_f64().unwrap()-e["previous_position"][1].as_f64().unwrap())*0.5)as f32;if ground{shade_ground_shadow(&mut c,&mask,x,yy,&gt);}else{shade_air_shadow(&mut c,&mask,x,yy,&air);}shadows.push(e["entity"].clone());count+=1;}if !ground{effects(&mut c,&cat,&mut foreign,s,true,&pal);}for e in s["enemies"].as_array().unwrap().iter().filter(|e|e["ground"].as_bool().unwrap()==ground){let asset=id(&e["asset"]);let im=if let Some(f)=(0x2009fu32..=0x200a0).position(|v|v==asset){if role==2{sprites[f][scale-1].1.clone()}else{sprites[f][scale-1].0.clone()}}else{select(&cat,&mut foreign,asset,scale,&pal)};let pos=at(e,scale);c.blit(&im,pos[0],pos[1]);order.push(e["entity"].clone());}}effects(&mut c,&cat,&mut foreign,s,false,&pal);roles.push(json!({"role":(["Original-target-fixed5636-foreign","current5636-target-fallback","proposed-derived-target-fixed5636-foreign"][role]),"files":emit(out,&format!("scene-{si}-s{scale}-r{role}"),&c.image),"actor_order":order,"Original_shadow_entities":shadows}));bodies.push(c.image);}
   assert_eq!(bodies[0].pixels,bodies[1].pixels);let mut changes=0;for yy in 0..200*scale{for x in 0..320*scale{let q=yy*320*scale+x;if bodies[1].pixels[q]!=bodies[2].pixels[q]{assert!(x>=p[0]as usize&&x<(p[0]as usize+width as usize*scale)&&yy>=p[1]as usize&&yy<(p[1]as usize+height as usize*scale));changes+=1;}}}
   rows.push(json!({"scene":si,"frame":frame,"asset":format!("{target_asset:05x}"),"tick":s["tick"],"scale":scale,"target_native_top_left":p,"target_canvas":[width as usize*scale,height as usize*scale],"target_canvas_clipped_samples":0,"all_target_occupied_samples_in_viewport":true,"current_baseline_equals_Original_target":true,"current_to_proposed_changes":changes,"outside_target_canvas_changes":0,"Original_shadows_target":false,"terrain_replacements":replacements.len(),"retained_terrain_placements":retained.len(),"palette_domain_placements":domains.len(),"roles":roles}));
  }
 }
 assert!(foreign.diagnostics.is_empty()&&target.diagnostics.is_empty());let palette:Vec<u8>=pal.into_iter().flatten().collect();std::fs::write(out.join("actual-palette-rgb.bin"),palette).unwrap();let proof=json!({"status":"ACTUAL_CONTROLLED_SHIP09G2_TWO_PHASE_ALL4_THREE_ROLES_SUCCESS","rows":rows,"actual_target_components":components,"diagnostics":[],"constructor_calls":1,"World_calls_in_constructor":0,"target_preblit_equals_frozen_G2_2009f_200a0_bank":true,"actual_Original_controls_render_upscale":true,"foreign_baseline":"immutable currentH5636 consumed whole-sequence projection and raw hardlinks; currentSourceG2 domain-aware joins","scope":"Controlled OriginalS2W9 SHIP09G2 complete2, one World retains exact raw4 declaration141 and normalpilot2; genuine Source field11=0 so no shadow. Terrain/enemies/Original shadows/main effects; excludes player/projectiles/pickups/secondary effects/UI/Host. Not natural mission/survival/purchase proof."});std::fs::write(out.join("actual-controlled-one-phase-composition-proof.json"),serde_json::to_vec_pretty(&proof).unwrap()).unwrap();println!("two saved controlled phases x all4 x three roles complete; diagnostics0; constructorWorld0");
}
fn main(){let a:Vec<String>=std::env::args().collect();match a.get(1).map(|v|v.as_str()){Some("capture")=>capture(&a),Some("compose")=>compose(&a),_=>panic!("capture or compose mode required")}}
